const IMGBB_LINK = /https?:\/\/(?:i\.)?ibb\.co\/[^\s"'<>)\\]+/g;

// Swaps known ImgBB links inside any value (text, HTML, JSON text, arrays, objects) for their Cloudinary copies.
export const moveImages = <T>(value: T): T => {
  if (typeof value === "string") {
    return (value.includes("ibb.co") ? value.replace(IMGBB_LINK, (url) => IMAGE_MOVES[url] || url) : value) as T;
  }
  if (Array.isArray(value)) return value.map(moveImages) as T;
  if (value && typeof value === "object" && Object.getPrototypeOf(value) === Object.prototype) {
    return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, moveImages(v)])) as T;
  }
  return value;
};
